using System;
using System.Collections.Generic;
using System.Globalization;
using System.Text;
using OnlyVolunteers.Map.Crowd;
using UnityEditor;
using UnityEditor.Animations;
using UnityEngine;
using C = OnlyVolunteers.Characters.Npc.NpcAnimContract;
using Object = UnityEngine.Object;

namespace OnlyVolunteers.Characters.Npc
{
    // Stage 9 step 5 (docs/drafts/NPC_RAGDOLL_ANIM_STAGE9_DESIGN.md §5.4, "the controller itself is generated by an editor
    // script"): rebuilds an NPC AnimatorController in place (the same asset, so SausageBuddy_Greybox.controller keeps its GUID)
    // from the clips of Animations/clips.json (GreyboxBuddySetup.InstallClips collects them into a Spec) and the Buddy FBX's
    // built-in Idle / Panic_Run_Loop / Panic_TurnFlee and Walk_v02. Deterministic and re-runnable: everything in the
    // controller is made here; edit clips.json or this file, never the controller.
    // Base layer, one flat state machine; the contract's parameters (NpcAnimContract) pick the mode:
    // - Entry routes, in this order: Ragdoll (an empty state: the Animator is off then), Down (the capsule lying: Idle),
    //   the escape (in a van and panicking: Escape_Scramble_Start, Escape_Scramble; else the run as Escape_Run), the cargo
    //   seat (in a van: Cargo_Sit_Idle, else Idle as Cargo_Sit), a crowd activity (Activity = its CrowdActivity: Enter,
    //   then Loop), then locomotion: Run (panicking, or above RunFrom), Walk (above WalkFrom), Idle.
    // - Every state leaves for the Exit node (and so back to Entry) as soon as its mode no longer holds; inside a mode the
    //   usual transitions: Idle / Walk / Run by Speed and Panic (WalkFrom, RunFrom), the idle variety and other clips.json
    //   links by exit time, an activity's loop to its exit clip when Activity changes, the knock from the sit idle
    //   (KnockOnWall). Speed-driven states play at SpeedMul.
    // - One-shots enter from Any State by their trigger and leave by exit time: the get-ups, SitUp_Cargo and JumpOut (the
    //   NPC itself starts these at frame 0 with Play, NpcAnimDriver.PlayGetUp), the hit reacts, the police punch (Beat),
    //   the fist shaken at the van and the fat officer's trip.
    // - All mode logic needs Driven (NpcAnimDriver sets it): without it the states only play when asked by name (the
    //   player's Buddy, GreyboxWalker; the locomotion preview).
    // Layers (only with their clips): UpperBody (override, Buddy_UpperBody.mask: Spine and up) aims while Aim
    // (Cop_Aim_Raise, then the Cop_Aim loop); Struggle (additive) loops the carried struggle while Carried and Groggy (the
    // capsule: the ragdoll's Animator is off). All states write no defaults (every clip keys every bone).
    public static class NpcAnimatorBuilder
    {
        public const string UpperBodyMaskPath = "Assets/OnlyVolunteers/Characters/SausageBuddy/Animations/Buddy_UpperBody.mask";

        /// <summary>What a controller is built from.</summary>
        public sealed class Spec
        {
            /// <summary>The built-in motions (the Buddy FBX's Idle, Panic_Run_Loop, Panic_TurnFlee, Walk_v02's Walk).</summary>
            public Motion Idle, Run, TurnFlee, Walk;
            /// <summary>clips.json: state name -> its clip (the clips) or the motion it reuses ("states").</summary>
            public readonly Dictionary<string, Motion> States = new();
            /// <summary>clips.json: role -> state name.</summary>
            public readonly Dictionary<string, string> Roles = new();
            /// <summary>clips.json links: exit-time transitions without parameters (the idle variety).</summary>
            public readonly List<(string from, string to, float exitTime, float blend)> Links = new();
            /// <summary>The prefab whose hierarchy the upper-body mask is made from.</summary>
            public string MaskPrefab;
        }

        private const AnimatorConditionMode If = AnimatorConditionMode.If, IfNot = AnimatorConditionMode.IfNot,
            Greater = AnimatorConditionMode.Greater, Less = AnimatorConditionMode.Less, EqualTo = AnimatorConditionMode.Equals,
            NotEqual = AnimatorConditionMode.NotEqual;
        private const float Move = 0.15f, Mode = 0.2f;

        private readonly struct Cond
        {
            public readonly AnimatorConditionMode Kind;
            public readonly float Threshold;
            public readonly string Parameter;

            public Cond(AnimatorConditionMode kind, string parameter, float threshold = 0f)
            {
                Kind = kind;
                Parameter = parameter;
                Threshold = threshold;
            }
        }

        private static Cond Is(string p) => new(If, p);
        private static Cond Not(string p) => new(IfNot, p);
        private static Cond Eq(string p, float v) => new(EqualTo, p, v);
        private static Cond Ne(string p, float v) => new(NotEqual, p, v);
        private static Cond Gt(string p, float v) => new(Greater, p, v);
        private static Cond Lt(string p, float v) => new(Less, p, v);
        private static Cond[] All(params Cond[] c) => c;

        // ---------- Entry point ----------

        /// <summary>Rebuilds 'controller' in place from 'spec'; returns a short report.</summary>
        public static string Build(AnimatorController controller, Spec spec)
        {
            if (controller == null) throw new ArgumentNullException(nameof(controller));
            if (spec.Idle == null || spec.Walk == null || spec.Run == null) throw new InvalidOperationException("NpcAnimatorBuilder: the built-in Idle, Walk and Run are needed");
            Wipe(controller);
            AddParameters(controller);
            var b = new Builder(controller, spec);
            b.BaseLayer();
            b.UpperBody();
            b.Struggle();
            b.Unplaced();
            EditorUtility.SetDirty(controller);
            NpcAnimDriver.ClearCache();
            return b.Report();
        }

        // Everything out of the asset: layers past the base, its states, transitions and blend trees, the parameters.
        private static void Wipe(AnimatorController controller)
        {
            while (controller.layers.Length > 1) controller.RemoveLayer(controller.layers.Length - 1);
            AnimatorStateMachine machine = controller.layers[0].stateMachine;
            foreach (AnimatorStateTransition t in machine.anyStateTransitions) machine.RemoveAnyStateTransition(t);
            foreach (AnimatorTransition t in machine.entryTransitions) machine.RemoveEntryTransition(t);
            foreach (ChildAnimatorStateMachine child in machine.stateMachines) machine.RemoveStateMachine(child.stateMachine);
            foreach (ChildAnimatorState child in machine.states) machine.RemoveState(child.state);
            string path = AssetDatabase.GetAssetPath(controller);
            foreach (Object o in AssetDatabase.LoadAllAssetsAtPath(path))
                if (o is BlendTree tree) Object.DestroyImmediate(tree, true);
            foreach (AnimatorControllerParameter p in controller.parameters) controller.RemoveParameter(p);
            AnimatorControllerLayer[] layers = controller.layers;
            layers[0].name = "Base Layer";
            layers[0].avatarMask = null;
            layers[0].blendingMode = AnimatorLayerBlendingMode.Override;
            controller.layers = layers;
        }

        private static void AddParameters(AnimatorController controller)
        {
            void Add(string name, AnimatorControllerParameterType type, float f = 0f, int i = 0, bool b = false) =>
                controller.AddParameter(new AnimatorControllerParameter { name = name, type = type, defaultFloat = f, defaultInt = i, defaultBool = b });
            Add(C.Speed, AnimatorControllerParameterType.Float);
            Add(C.SpeedMul, AnimatorControllerParameterType.Float, 1f);
            Add(C.Panic, AnimatorControllerParameterType.Bool);
            Add(C.StunPhase, AnimatorControllerParameterType.Int);
            Add(C.Carried, AnimatorControllerParameterType.Bool);
            Add(C.InCargo, AnimatorControllerParameterType.Bool);
            Add(C.Activity, AnimatorControllerParameterType.Int, i: -1);
            Add(C.Ragdoll, AnimatorControllerParameterType.Bool);
            Add(C.GetUp, AnimatorControllerParameterType.Int);
            Add(C.Gait, AnimatorControllerParameterType.Float);
            Add(C.Aim, AnimatorControllerParameterType.Bool);
            Add(C.Driven, AnimatorControllerParameterType.Bool);
            foreach (string trigger in C.GetUpTriggers)
                if (trigger != null) Add(trigger, AnimatorControllerParameterType.Trigger);
            foreach (string trigger in C.Triggers) Add(trigger, AnimatorControllerParameterType.Trigger);
        }

        // ---------- The build ----------

        private sealed class Builder
        {
            private readonly AnimatorController _controller;
            private readonly Spec _spec;
            private AnimatorStateMachine _machine;
            private readonly Dictionary<string, AnimatorState> _states = new();
            private readonly HashSet<string> _placed = new();
            private readonly HashSet<string> _linked = new();
            private readonly List<int> _activities = new();
            private readonly StringBuilder _report = new();
            private int _transitions;

            public Builder(AnimatorController controller, Spec spec)
            {
                _controller = controller;
                _spec = spec;
                foreach ((string from, _, _, _) in spec.Links) _linked.Add(from);
            }

            public string Report() =>
                $"[NpcAnimatorBuilder] {AssetDatabase.GetAssetPath(_controller)}: {_states.Count} states, {_transitions} transitions, " +
                $"{_controller.layers.Length} layers, {_controller.parameters.Length} parameters; activities with clips: " +
                (_activities.Count > 0 ? string.Join(", ", _activities.ConvertAll(a => ((CrowdActivity)a).ToString())) : "none") + "\n" + _report;

            private Motion RoleMotion(string role) =>
                _spec.Roles.TryGetValue(role, out string state) && _spec.States.TryGetValue(state, out Motion m) ? m : null;

            private string RoleState(string role) => _spec.Roles.TryGetValue(role, out string state) && _spec.States.ContainsKey(state) ? state : null;

            // ---------- Base layer ----------

            public void BaseLayer()
            {
                _machine = _controller.layers[0].stateMachine;
                _machine.anyStatePosition = new Vector3(20f, -120f, 0f);
                _machine.entryPosition = new Vector3(20f, 0f, 0f);
                _machine.exitPosition = new Vector3(20f, 120f, 0f);

                // Locomotion (the default), its idle variety and the legacy TurnFlee.
                AnimatorState idle = State(C.IdleState, RoleMotion(C.RoleIdle) ?? _spec.Idle, 300f, 0f, true);
                AnimatorState walk = State(C.WalkState, RoleMotion(C.RoleWalk) ?? _spec.Walk, 300f, 60f, true);
                AnimatorState run = State(C.RunState, RunMotion(), 300f, 120f, true);
                _machine.defaultState = idle;
                var locomotion = new List<AnimatorState> { idle, walk, run };
                float y = 200f;
                foreach (KeyValuePair<string, Motion> s in _spec.States)
                    if (IsIdleVariant(s.Key))
                    {
                        locomotion.Add(State(s.Key, s.Value, 300f, y, false));
                        y += 60f;
                    }
                if (_spec.TurnFlee != null)
                {
                    AnimatorState turn = State("TurnFlee", _spec.TurnFlee, 300f, y, false);
                    ToExitAtEnd(turn, Move);
                }

                // Down (the capsule lying: the standing idle) and Ragdoll (the Animator is off).
                AnimatorState down = State(C.DownState, idle.motion, 600f, 0f, false);
                AnimatorState ragdoll = State(C.RagdollState, null, 600f, 60f, false);

                // The van: the seat (sit idle, knock), the escape, the sit-up.
                string sitName = RoleState(C.RoleSitIdle);
                AnimatorState sit = State(sitName ?? C.CargoFallbackState, sitName != null ? _spec.States[sitName] : _spec.Idle, 900f, 0f, false);
                var cargo = new List<AnimatorState> { sit };
                AnimatorState knock = RoleOneShot(C.RoleKnock, 900f, 60f);
                if (knock != null)
                {
                    cargo.Add(knock);
                    Transition(sit, knock, 0.2f, All(Is(C.Triggers[(int)NpcAnimTrigger.KnockOnWall])));
                    if (!_linked.Contains(knock.name)) Link(knock, sit, 1f, 0.2f);
                }
                string scrambleName = RoleState(C.RoleScramble);
                AnimatorState scramble = State(scrambleName ?? C.EscapeFallbackState, scrambleName != null ? _spec.States[scrambleName] : run.motion, 900f, 180f, true);
                AnimatorState scrambleStart = RoleOneShot(C.RoleScrambleStart, 900f, 120f);
                var escape = new List<AnimatorState> { scramble };
                if (scrambleStart != null)
                {
                    escape.Add(scrambleStart);
                    if (!_linked.Contains(scrambleStart.name)) Link(scrambleStart, scramble, 1f, 0.1f);
                }
                AnimatorState sitUp = RoleOneShot(C.RoleSitUp, 900f, 240f);
                if (sitUp != null)
                {
                    AnyTrigger(sitUp, C.GetUpTriggers[(int)GetUpKind.SitUp], 0f, false);
                    if (!_linked.Contains(sitUp.name)) Link(sitUp, sit, 1f, 0.1f);
                    ModeExits(sitUp, CargoBroken());
                }

                // Crowd activities: Enter -> Loop -> (Activity changed) Exit.
                var activityStates = new List<(int activity, AnimatorState enter, AnimatorState loop, AnimatorState exit)>();
                float ax = 1500f;
                foreach (CrowdActivity a in (CrowdActivity[])Enum.GetValues(typeof(CrowdActivity)))
                {
                    string name = a.ToString();
                    AnimatorState loop = RoleOneShot(C.ActivityRole(name, C.LoopPhase), ax, 60f);
                    if (loop == null) continue;
                    AnimatorState enter = RoleOneShot(C.ActivityRole(name, C.EnterPhase), ax, 0f);
                    AnimatorState exit = RoleOneShot(C.ActivityRole(name, C.ExitPhase), ax, 120f);
                    activityStates.Add(((int)a, enter, loop, exit));
                    _activities.Add((int)a);
                    ax += 260f;
                }

                // Entry: the modes in priority order, then locomotion (default Idle).
                Entry(ragdoll, Is(C.Ragdoll));
                Entry(down, Gt(C.StunPhase, 0), Lt(C.StunPhase, 3), Not(C.Ragdoll));
                Entry(scrambleStart ?? scramble, Is(C.InCargo), Is(C.Panic), Not(C.Ragdoll));
                Entry(sit, Is(C.InCargo), Not(C.Ragdoll));
                foreach ((int a, AnimatorState enter, AnimatorState loop, _) in activityStates)
                    Entry(enter ?? loop, Eq(C.Activity, a), Eq(C.StunPhase, 0), Not(C.InCargo), Not(C.Panic), Not(C.Ragdoll));
                Entry(run, Is(C.Panic), Gt(C.Speed, C.WalkFrom));
                Entry(run, Gt(C.Speed, C.RunFrom));
                Entry(walk, Gt(C.Speed, C.WalkFrom));

                // Leaving a mode (to Exit, Entry picks the next).
                var locomotionExits = new List<Cond[]> { All(Is(C.Ragdoll)), All(Eq(C.StunPhase, 1)), All(Eq(C.StunPhase, 2)), All(Is(C.InCargo)) };
                foreach ((int a, _, _, _) in activityStates) locomotionExits.Add(All(Eq(C.Activity, a)));
                foreach (AnimatorState s in locomotion) ModeExits(s, locomotionExits.ToArray());
                ModeExits(down, All(Lt(C.StunPhase, 1)), All(Gt(C.StunPhase, 2)), All(Is(C.Ragdoll)));
                ModeExits(ragdoll, All(Not(C.Ragdoll)));
                foreach (AnimatorState s in cargo) ModeExits(s, CargoBroken());
                foreach (AnimatorState s in escape)
                    ModeExits(s, All(Not(C.InCargo)), All(Not(C.Panic)), All(Is(C.Ragdoll)), All(Eq(C.StunPhase, 1)), All(Eq(C.StunPhase, 2)));
                foreach ((int a, AnimatorState enter, AnimatorState loop, AnimatorState exit) in activityStates)
                {
                    Cond[][] broken = { All(Is(C.Ragdoll)), All(Ne(C.StunPhase, 0)), All(Is(C.InCargo)), All(Is(C.Panic)) };
                    if (enter != null)
                    {
                        ModeExits(enter, broken);
                        ModeExits(enter, All(Ne(C.Activity, a)));
                        if (!_linked.Contains(enter.name)) Link(enter, loop, 1f, 0.2f);
                    }
                    ModeExits(loop, broken);
                    if (exit != null)
                    {
                        Transition(loop, exit, 0.25f, All(Is(C.Driven), Ne(C.Activity, a)));
                        ModeExits(exit, broken);
                        ToExitAtEnd(exit, Mode);
                    }
                    else ModeExits(loop, All(Ne(C.Activity, a)));
                }

                // Locomotion inside its mode.
                foreach (AnimatorState s in locomotion)
                {
                    if (s == run) continue;
                    Transition(s, run, Move, All(Is(C.Driven), Is(C.Panic), Gt(C.Speed, C.WalkFrom)));
                    Transition(s, run, Move, All(Is(C.Driven), Gt(C.Speed, C.RunFrom)));
                    if (s != walk) Transition(s, walk, Move, All(Is(C.Driven), Gt(C.Speed, C.WalkFrom)));
                }
                Transition(walk, idle, Move, All(Is(C.Driven), Lt(C.Speed, C.WalkFrom)));
                Transition(run, idle, Move, All(Is(C.Driven), Lt(C.Speed, C.WalkFrom)));
                Transition(run, walk, Move, All(Is(C.Driven), Not(C.Panic), Lt(C.Speed, C.RunFrom), Gt(C.Speed, C.WalkFrom)));

                // One-shots by trigger from Any State; out by exit time (Entry then picks the mode).
                float oy = 0f;
                foreach (GetUpKind kind in new[] { GetUpKind.Back, GetUpKind.Belly, GetUpKind.JumpOut })
                {
                    AnimatorState s = RoleOneShot(C.RoleOf(kind), 1200f, oy);
                    oy += 60f;
                    if (s == null) continue;
                    AnyTrigger(s, C.GetUpTriggers[(int)kind], 0f, false);
                    ModeExits(s, All(Is(C.Ragdoll)), All(Eq(C.StunPhase, 1)), All(Eq(C.StunPhase, 2)));
                    if (!_linked.Contains(s.name)) ToExitAtEnd(s, kind == GetUpKind.JumpOut ? 0.1f : Move);
                }
                foreach (NpcAnimTrigger trigger in new[] { NpcAnimTrigger.HitFront, NpcAnimTrigger.HitBack, NpcAnimTrigger.HitHead })
                {
                    AnimatorState s = RoleOneShot(C.RoleOf(trigger), 1200f, oy);
                    oy += 60f;
                    if (s == null) continue;
                    AnyTrigger(s, C.Triggers[(int)trigger], 0.08f, true);
                    ModeExits(s, All(Is(C.Ragdoll)));
                    ToExitAtEnd(s, Move);
                }
                AnimatorState stagger = RoleOneShot(C.RoleStagger, 1200f, oy);
                oy += 60f;
                if (stagger != null)
                {
                    AnyTrigger(stagger, C.Triggers[(int)NpcAnimTrigger.Stagger], 0.1f, true);
                    ModeExits(stagger, All(Is(C.Ragdoll)), All(Eq(C.StunPhase, 1)), All(Eq(C.StunPhase, 2)));
                    ToExitAtEnd(stagger, Mode);
                }
                AnimatorState punch = RoleOneShot(C.RolePunch, 1200f, oy);
                oy += 60f;
                if (punch != null)
                {
                    AnyTrigger(punch, C.Triggers[(int)NpcAnimTrigger.Beat], 0.1f, true);
                    ModeExits(punch, All(Is(C.Ragdoll)), All(Eq(C.StunPhase, 1)), All(Eq(C.StunPhase, 2)));
                    // Running again after the blow (the wind-up's 0.45 s): out early.
                    AnimatorStateTransition early = punch.AddExitTransition();
                    Setup(early, Move, true, 0.55f);
                    early.AddCondition(Greater, 0.5f, C.Speed);
                    _transitions++;
                    ToExitAtEnd(punch, Move);
                }
                AnimatorState fist = RoleOneShot(C.RoleShakeFist, 1200f, oy);
                oy += 60f;
                if (fist != null)
                {
                    AnyTrigger(fist, C.Triggers[(int)NpcAnimTrigger.ShakeFist], 0.15f, false);
                    ModeExits(fist, All(Is(C.Ragdoll)), All(Eq(C.StunPhase, 1)), All(Eq(C.StunPhase, 2)), All(Gt(C.Speed, 0.5f)));
                    ToExitAtEnd(fist, Mode);
                }
                AnimatorState trip = RoleOneShot(C.RoleTrip, 1200f, oy);
                if (trip != null)
                {
                    AnyTrigger(trip, C.Triggers[(int)NpcAnimTrigger.Trip], 0.05f, false);
                    ModeExits(trip, All(Is(C.Ragdoll)));
                    ToExitAtEnd(trip, 0.1f);
                }

                // clips.json links (the idle variety): exit time, no parameters.
                foreach ((string from, string to, float exitTime, float blend) in _spec.Links)
                {
                    if (!_states.TryGetValue(from, out AnimatorState a) || !_states.TryGetValue(to, out AnimatorState b))
                        throw new InvalidOperationException($"clips.json link {from} -> {to}: no such state");
                    Link(a, b, exitTime, blend);
                }
            }

            // The cargo seat's mode no longer holds: out of the van, panicking (the escape), a ragdoll, knocked out.
            private static Cond[][] CargoBroken() =>
                new[] { All(Not(C.InCargo)), All(Is(C.Panic)), All(Is(C.Ragdoll)), All(Eq(C.StunPhase, 1)), All(Eq(C.StunPhase, 2)) };

            private bool IsIdleVariant(string state)
            {
                foreach (KeyValuePair<string, string> r in _spec.Roles)
                    if (r.Value == state) return r.Key != C.RoleIdle && r.Key.StartsWith(C.RoleIdle, StringComparison.Ordinal);
                // A "states" entry without a role reusing the Idle (the idle variety's rest).
                return _spec.States[state] == (RoleMotion(C.RoleIdle) ?? _spec.Idle);
            }

            // The run: the civilian's, blended by Gait with the police runs when the rig has them.
            private Motion RunMotion()
            {
                Motion civilian = RoleMotion(C.RoleRun) ?? _spec.Run;
                Motion cop = RoleMotion(C.RoleRunCop), fat = RoleMotion(C.RoleRunCopFat);
                if (cop == null && fat == null) return civilian;
                foreach (string role in new[] { C.RoleRunCop, C.RoleRunCopFat })
                    if (RoleState(role) is string state) _placed.Add(state); // children of the Run state, not states
                var tree = new BlendTree
                {
                    name = "Run_Gait",
                    blendType = BlendTreeType.Simple1D,
                    blendParameter = C.Gait,
                    useAutomaticThresholds = false,
                    hideFlags = HideFlags.HideInHierarchy,
                };
                AssetDatabase.AddObjectToAsset(tree, _controller);
                tree.AddChild(civilian, (float)NpcGait.Civilian);
                tree.AddChild(cop ?? civilian, (float)NpcGait.Police);
                tree.AddChild(fat ?? cop ?? civilian, (float)NpcGait.PoliceFat);
                _report.AppendLine($"  Run blends by Gait: {civilian.name} / {(cop ?? civilian).name} / {(fat ?? cop ?? civilian).name}");
                return tree;
            }

            // ---------- Upper body (aiming) ----------

            public void UpperBody()
            {
                Motion raise = RoleMotion(C.RoleAimRaise), aim = RoleMotion(C.RoleAim);
                if (raise == null && aim == null) return;
                AvatarMask mask = UpperBodyMask(_spec.MaskPrefab);
                AnimatorStateMachine machine = AddLayer(C.UpperBodyLayer, AnimatorLayerBlendingMode.Override, mask);
                AnimatorState empty = Add(machine, C.EmptyState, null, 300f, 0f);
                machine.defaultState = empty;
                var aiming = new List<AnimatorState>();
                if (raise != null) aiming.Add(Placed(Add(machine, RoleState(C.RoleAimRaise), raise, 600f, 0f)));
                if (aim != null) aiming.Add(Placed(Add(machine, RoleState(C.RoleAim), aim, 600f, 60f)));
                Transition(empty, aiming[0], Move, All(Is(C.Driven), Is(C.Aim), Not(C.Ragdoll)));
                if (aiming.Count == 2) Link(aiming[0], aiming[1], 1f, 0.05f);
                foreach (AnimatorState s in aiming)
                {
                    Transition(s, empty, 0.25f, All(Not(C.Aim)));
                    Transition(s, empty, 0f, All(Is(C.Ragdoll)));
                }
                _report.AppendLine($"  layer {C.UpperBodyLayer}: aim {(raise != null ? raise.name + " -> " : "")}{(aim != null ? aim.name : "")}, mask {UpperBodyMaskPath}");
            }

            // ---------- Carried struggle (additive, the capsule) ----------

            public void Struggle()
            {
                Motion struggle = RoleMotion(C.RoleStruggle);
                if (struggle == null) return;
                AnimatorStateMachine machine = AddLayer(C.StruggleLayer, AnimatorLayerBlendingMode.Additive, null);
                AnimatorState empty = Add(machine, C.EmptyState, null, 300f, 0f);
                machine.defaultState = empty;
                AnimatorState s = Placed(Add(machine, RoleState(C.RoleStruggle), struggle, 600f, 0f));
                Transition(empty, s, 0.3f, All(Is(C.Driven), Is(C.Carried), Eq(C.StunPhase, 2), Not(C.Ragdoll)));
                Transition(s, empty, 0.3f, All(Not(C.Carried)));
                Transition(s, empty, 0.3f, All(Ne(C.StunPhase, 2)));
                Transition(s, empty, 0f, All(Is(C.Ragdoll)));
                _report.AppendLine($"  layer {C.StruggleLayer}: additive {struggle.name} while Carried and Groggy");
            }

            private AnimatorStateMachine AddLayer(string name, AnimatorLayerBlendingMode blending, AvatarMask mask)
            {
                _controller.AddLayer(name);
                AnimatorControllerLayer[] layers = _controller.layers;
                int i = layers.Length - 1;
                layers[i].defaultWeight = 1f;
                layers[i].blendingMode = blending;
                layers[i].avatarMask = mask;
                _controller.layers = layers;
                return _controller.layers[i].stateMachine;
            }

            // ---------- Helpers ----------

            private AnimatorState State(string name, Motion motion, float x, float y, bool speedParameter)
            {
                if (_states.ContainsKey(name)) throw new InvalidOperationException("NpcAnimatorBuilder: two states named " + name);
                AnimatorState s = Add(_machine, name, motion, x, y);
                if (speedParameter)
                {
                    s.speedParameterActive = true;
                    s.speedParameter = C.SpeedMul;
                }
                _states[name] = s;
                return Placed(s);
            }

            private AnimatorState Placed(AnimatorState s)
            {
                _placed.Add(s.name);
                return s;
            }

            // clips.json clips whose role the build does not use (yet): plain states in the base layer, entered only by name
            // and leaving at their end, so every manifest clip is in the controller.
            public void Unplaced()
            {
                float y = 0f;
                foreach (KeyValuePair<string, Motion> s in _spec.States)
                {
                    if (_placed.Contains(s.Key)) continue;
                    AnimatorState state = State(s.Key, s.Value, 1800f + (_activities.Count > 0 ? 260f * _activities.Count : 0f), y, false);
                    ToExitAtEnd(state, Mode);
                    _report.AppendLine($"  {s.Key}: no place for its role, a plain state (played by name only)");
                    y += 60f;
                }
            }

            private static AnimatorState Add(AnimatorStateMachine machine, string name, Motion motion, float x, float y)
            {
                AnimatorState s = machine.AddState(name, new Vector3(x, y, 0f));
                s.motion = motion;
                s.writeDefaultValues = false;
                return s;
            }

            // The state of a role's clip, or null when clips.json has none.
            private AnimatorState RoleOneShot(string role, float x, float y)
            {
                string name = RoleState(role);
                return name == null ? null : _states.TryGetValue(name, out AnimatorState known) ? known : State(name, _spec.States[name], x, y, false);
            }

            private void Entry(AnimatorState to, params Cond[] conditions)
            {
                AnimatorTransition t = _machine.AddEntryTransition(to);
                t.AddCondition(If, 0f, C.Driven);
                foreach (Cond c in conditions) t.AddCondition(c.Kind, c.Threshold, c.Parameter);
                _transitions++;
            }

            // One exit (to Exit, then Entry) per condition set: the mode no longer holds.
            private void ModeExits(AnimatorState from, params Cond[][] whenAny)
            {
                foreach (Cond[] conditions in whenAny)
                {
                    AnimatorStateTransition t = from.AddExitTransition();
                    Setup(t, Mode, false, 0f);
                    t.AddCondition(If, 0f, C.Driven);
                    foreach (Cond c in conditions) t.AddCondition(c.Kind, c.Threshold, c.Parameter);
                    _transitions++;
                }
            }

            private void ToExitAtEnd(AnimatorState from, float blend)
            {
                AnimatorStateTransition t = from.AddExitTransition();
                Setup(t, blend, true, 1f);
                _transitions++;
            }

            private void Transition(AnimatorState from, AnimatorState to, float blend, Cond[] conditions)
            {
                AnimatorStateTransition t = from.AddTransition(to);
                Setup(t, blend, false, 0f);
                foreach (Cond c in conditions) t.AddCondition(c.Kind, c.Threshold, c.Parameter);
                _transitions++;
            }

            private void Link(AnimatorState from, AnimatorState to, float exitTime, float blend)
            {
                AnimatorStateTransition t = from.AddTransition(to);
                Setup(t, blend, true, exitTime);
                _transitions++;
            }

            private void AnyTrigger(AnimatorState to, string trigger, float blend, bool canTransitionToSelf)
            {
                AnimatorStateTransition t = _machine.AddAnyStateTransition(to);
                Setup(t, blend, false, 0f);
                t.canTransitionToSelf = canTransitionToSelf;
                t.AddCondition(If, 0f, trigger);
                _transitions++;
            }

            private static void Setup(AnimatorStateTransition t, float blend, bool exitTime, float at)
            {
                t.hasExitTime = exitTime;
                t.exitTime = at;
                t.hasFixedDuration = true;
                t.duration = blend;
                t.offset = 0f;
                t.interruptionSource = TransitionInterruptionSource.None;
            }
        }

        // ---------- The upper-body mask ----------

        /// <summary>The Generic upper-body mask (Spine and every bone under it) made from the prefab's hierarchy, created or
        /// updated at UpperBodyMaskPath.</summary>
        public static AvatarMask UpperBodyMask(string prefabPath)
        {
            var prefab = AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath);
            if (prefab == null) throw new InvalidOperationException("NpcAnimatorBuilder: no prefab for the upper-body mask: " + prefabPath);
            var mask = AssetDatabase.LoadAssetAtPath<AvatarMask>(UpperBodyMaskPath);
            if (mask == null)
            {
                mask = new AvatarMask();
                AssetDatabase.CreateAsset(mask, UpperBodyMaskPath);
            }
            var paths = new List<string>();
            foreach (Transform t in prefab.GetComponentsInChildren<Transform>(true))
                if (t != prefab.transform) paths.Add(AnimationUtility.CalculateTransformPath(t, prefab.transform));
            mask.transformCount = paths.Count;
            for (int i = 0; i < paths.Count; i++)
            {
                mask.SetTransformPath(i, paths[i]);
                mask.SetTransformActive(i, paths[i].Contains("mixamorig:Spine"));
            }
            EditorUtility.SetDirty(mask);
            return mask;
        }

        internal static string Inv(FormattableString s) => s.ToString(CultureInfo.InvariantCulture);
    }
}
